/bin/bash -lc "node --input-type=module <<'JS'
import {readdirSync,readFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
let checked=0;
for (const dir of ['src','test','test/fixtures']) for (const file of readdirSync(dir).filter(f=>f.endsWith('.ts'))) {
 const target="'`${dir}/${file}`;
 const r=spawnSync(process.execPath,['"'--check',target],{encoding:'utf8'});
 if(r.status"'!==0){process.stderr.write(r.stderr);process.exitCode=1;}
 if(readFileSync(target,'"'utf8').split('\\n').some(l=>/[\\t ]+"'$/.test(l))){console.error('"'行尾空白：'+target);process.exitCode=1;}
 checked++;
}
if("'!process.exitCode) console.log(`${checked} 个 TypeScript 文件语法检查通过，无行尾空白`);
